#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentEffort {
    Fast,
    Auto,
    Pro,
}

impl AgentEffort {
    fn parse(value: &str) -> Self {
        match value.trim().to_ascii_lowercase().as_str() {
            "fast" => Self::Fast,
            "pro" => Self::Pro,
            _ => Self::Auto,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Fast => "fast",
            Self::Auto => "auto",
            Self::Pro => "pro",
        }
    }

    fn requested_policy(self) -> OrchestrationPolicy {
        match self {
            Self::Fast => OrchestrationPolicy::Single,
            Self::Auto => OrchestrationPolicy::AutoRouter,
            Self::Pro => OrchestrationPolicy::BestOfN { candidates: 3 },
        }
    }
}

fn collaboration_profile(effort: AgentEffort, context: &RoutingContext) -> &'static str {
    if effort == AgentEffort::Pro
        && context.complexity_score <= 1
        && context.estimated_steps <= 2
        && !context.needs_multi_model
        && !context.needs_retrieval
        && !context.needs_vision
        && !context.high_stakes
        && !context.parallelizable
        && !context.verification_required
    {
        "bounded"
    } else {
        "adaptive"
    }
}

fn default_agent_effort() -> String {
    AgentEffort::Auto.label().to_string()
}

impl Default for ProviderConfig {
    fn default() -> Self {
        let model = "gpt-4.1-mini".to_string();
        Self {
            base_url: "https://api.openai.com/v1".to_string(),
            api_key: String::new(),
            model: model.clone(),
            conductor_model: model.clone(),
            planner_model: model.clone(),
            executor_model: model.clone(),
            reviewer_model: model.clone(),
            summarizer_model: model,
            embedding_model: OPENAI_DEFAULT_EMBEDDING_MODEL.to_string(),
            image_model: String::new(),
            image_endpoint: String::new(),
            collaboration_policy: "auto_router".to_string(),
            prompt_evolution_enabled: true,
            context_window_tokens: 128_000,
            agent_system_prompt: String::new(),
        }
    }
}

impl ProviderConfig {
    fn is_ready(&self) -> bool {
        !self.base_url.trim().is_empty()
            && !self.api_key.trim().is_empty()
            && !self.executor_model.trim().is_empty()
    }

    fn model_for_role(&self, role: &ModelRole) -> String {
        if *role == ModelRole::Embedder {
            return embedding_model_for_provider(&self.base_url, &self.embedding_model);
        }
        let model = match role {
            ModelRole::Planner => &self.planner_model,
            ModelRole::Executor => &self.executor_model,
            ModelRole::Reviewer => &self.reviewer_model,
            ModelRole::Summarizer => &self.summarizer_model,
            ModelRole::Embedder => unreachable!("embedder handled above"),
        };

        if model.trim().is_empty() {
            self.model.clone()
        } else {
            model.clone()
        }
    }

    fn model_for_conductor(&self) -> String {
        if self.conductor_model.trim().is_empty() {
            self.model_for_role(&ModelRole::Planner)
        } else {
            self.conductor_model.clone()
        }
    }

    fn model_for_agent_policy(&self, policy: &OrchestrationPolicy) -> String {
        if *policy == OrchestrationPolicy::Single && !self.model.trim().is_empty() {
            self.model.clone()
        } else {
            self.model_for_role(&ModelRole::Executor)
        }
    }
}

fn embedding_model_for_provider(base_url: &str, configured_model: &str) -> String {
    let configured_model = configured_model.trim();
    let normalized_url = base_url.trim().to_ascii_lowercase();
    let is_dashscope =
        normalized_url.contains("dashscope") && normalized_url.contains("aliyuncs.com");
    if is_dashscope
        && (configured_model.is_empty()
            || configured_model.eq_ignore_ascii_case(OPENAI_DEFAULT_EMBEDDING_MODEL))
    {
        DASHSCOPE_DEFAULT_EMBEDDING_MODEL.to_string()
    } else if configured_model.is_empty() {
        OPENAI_DEFAULT_EMBEDDING_MODEL.to_string()
    } else {
        configured_model.to_string()
    }
}

fn agent_model_for_run(config: &ProviderConfig, run_context: &Metadata) -> String {
    if let Some(model) = run_context
        .get("agent_model")
        .filter(|model| !model.trim().is_empty())
    {
        return model.clone();
    }
    let policy = run_context
        .get("collaboration_policy")
        .and_then(|label| parse_policy(label));
    policy
        .as_ref()
        .map(|policy| config.model_for_agent_policy(policy))
        .unwrap_or_else(|| config.model_for_role(&ModelRole::Executor))
}

fn agent_model_for_effort(
    config: &ProviderConfig,
    effort: AgentEffort,
    policy: &OrchestrationPolicy,
    routing_decision: &RoutingDecision,
) -> String {
    match effort {
        AgentEffort::Fast if !config.model.trim().is_empty() => config.model.clone(),
        AgentEffort::Auto if !routing_decision.model.trim().is_empty() => {
            routing_decision.model.clone()
        }
        AgentEffort::Fast | AgentEffort::Auto | AgentEffort::Pro => {
            config.model_for_agent_policy(policy)
        }
    }
}

