fn begin_agent_run_control_for_effort(
    state: &tauri::State<'_, AppState>,
    session_id: &str,
    effort: &str,
    snapshot: Option<RunControlSnapshot>,
) -> Result<Arc<AgentRunControl>, String> {
    cancel_background_prompt_evaluations(state)?;
    let control = Arc::new(
        snapshot
            .map(AgentRunControl::from_snapshot)
            .unwrap_or_else(|| AgentRunControl::new(effort)),
    );
    let mut controls = state
        .agent_run_controls
        .lock()
        .map_err(|error| format!("agent run control lock poisoned: {error}"))?;
    if controls.contains_key(session_id) {
        return Err("agent run is already active for this session".to_string());
    }
    controls.insert(session_id.to_string(), control.clone());
    Ok(control)
}

fn cancel_background_prompt_evaluations(
    state: &tauri::State<'_, AppState>,
) -> Result<(), String> {
    let controls = state
        .prompt_evaluation_controls
        .lock()
        .map_err(|error| format!("prompt evaluation control lock poisoned: {error}"))?;
    for control in controls.values() {
        control.request_cancel();
    }
    Ok(())
}

fn active_agent_run_control(
    state: &tauri::State<'_, AppState>,
    session_id: Option<&str>,
) -> Result<Option<Arc<AgentRunControl>>, String> {
    let Some(session_id) = session_id else {
        return Ok(None);
    };
    Ok(state
        .agent_run_controls
        .lock()
        .map_err(|error| format!("agent run control lock poisoned: {error}"))?
        .get(session_id)
        .cloned())
}

fn finish_agent_run_control(
    state: &tauri::State<'_, AppState>,
    session_id: &str,
    control: &Arc<AgentRunControl>,
) -> Result<(), String> {
    let mut controls = state
        .agent_run_controls
        .lock()
        .map_err(|error| format!("agent run control lock poisoned: {error}"))?;
    if controls
        .get(session_id)
        .is_some_and(|current| Arc::ptr_eq(current, control))
    {
        controls.remove(session_id);
    }
    Ok(())
}

fn request_agent_run_cancel(
    state: &tauri::State<'_, AppState>,
    session_id: &str,
) -> Result<bool, String> {
    if let Some(control) = active_agent_run_control(state, Some(session_id))? {
        control.request_cancel();
        return Ok(true);
    }
    Ok(false)
}

fn agent_run_should_stop(control: &Arc<AgentRunControl>) -> bool {
    control.should_stop()
}

fn add_agent_run_budget_metadata(metadata: &mut Metadata, control: &AgentRunControl) {
    let budget = control.budget();
    metadata.insert(
        "run_budget_ms".to_string(),
        budget.max_duration.as_millis().to_string(),
    );
    metadata.insert(
        "run_model_call_budget".to_string(),
        budget.max_model_calls.to_string(),
    );
    metadata.insert(
        "run_initial_model_calls".to_string(),
        budget.initial_model_calls.to_string(),
    );
    metadata.insert(
        "run_tool_call_budget".to_string(),
        budget.max_tool_calls.to_string(),
    );
    metadata.insert(
        "run_initial_tool_calls".to_string(),
        budget.initial_tool_calls.to_string(),
    );
    metadata.insert(
        "run_model_timeout_ms".to_string(),
        budget.model_call_timeout.as_millis().to_string(),
    );
    metadata.insert(
        "run_no_progress_ms".to_string(),
        budget.no_progress_timeout.as_millis().to_string(),
    );
}

