#[allow(clippy::too_many_arguments)]
fn phase7_state(
    store: &SqliteStore,
    adapter: &FileRagAdapter,
    memory: MemoryStatsView,
    sources: Vec<RagSourceView>,
    retrieval_trace: Option<RetrievalTraceView>,
    graph: GraphStateView,
    answer: Option<String>,
    last_error: Option<String>,
) -> Result<Phase7State, StorageError> {
    let events = store.list_by_task(&phase7_task_id())?;
    let timeline = events
        .iter()
        .cloned()
        .map(|event| timeline_entry(event, &[]))
        .collect();
    let answer = answer.or_else(|| events.iter().rev().find_map(rag_answer_from_event));

    Ok(Phase7State {
        timeline,
        stats: rag_stats_view(adapter.stats()),
        memory,
        sources,
        retrieval_trace,
        graph,
        answer,
        last_error,
    })
}

fn phase7_state_with_error(
    state: &tauri::State<'_, AppState>,
    message: impl Into<String>,
    sources: Vec<RagSourceView>,
    answer: Option<String>,
) -> Result<Phase7State, String> {
    let message = message.into();
    let root = active_workspace_root(state)?;
    let project_id = active_project_id_for_memory(state)?;
    let (adapter, _) = cached_rag_adapter_for(state, &root)?;
    let focus_paths = sources
        .iter()
        .map(|source| source.path.clone())
        .collect::<Vec<_>>();
    let graph = graph_state_for(&root, &focus_paths).unwrap_or_else(|_| empty_graph_state());
    let mut store = state
        .store
        .lock()
        .map_err(|error| format!("store lock poisoned: {error}"))?;
    append_event(
        &mut store,
        &phase7_task_id(),
        EventKind::Error,
        "RAG request failed",
        [("error".to_string(), message.clone())]
            .into_iter()
            .collect(),
    )
    .map_err(|error| error.to_string())?;
    let memory = project_memory_stats(&mut store, project_id.as_deref())
        .map_err(|error| error.to_string())?;

    phase7_state(
        &store,
        &adapter,
        memory,
        sources,
        None,
        graph,
        answer,
        Some(message),
    )
    .map_err(|error| error.to_string())
}

