fn workspace_knowledge_cache_key(workspace_root: &Path) -> String {
    fs::canonicalize(workspace_root)
        .unwrap_or_else(|_| workspace_root.to_path_buf())
        .display()
        .to_string()
}

fn cached_rag_adapter_for(
    state: &tauri::State<'_, AppState>,
    workspace_root: &Path,
) -> Result<(FileRagAdapter, bool), String> {
    let key = workspace_knowledge_cache_key(workspace_root);
    if let Some(entry) = state
        .workspace_knowledge_cache
        .lock()
        .map_err(|error| format!("workspace knowledge cache lock poisoned: {error}"))?
        .get(&key)
        .filter(|entry| entry.validated_at.elapsed() <= WORKSPACE_KNOWLEDGE_CACHE_TTL)
        .cloned()
    {
        return Ok((entry.adapter, true));
    }
    open_rag_adapter_for(workspace_root).map(|adapter| (adapter, false))
}

fn cache_rag_adapter(
    state: &tauri::State<'_, AppState>,
    workspace_root: &Path,
    adapter: &FileRagAdapter,
) -> Result<(), String> {
    let key = workspace_knowledge_cache_key(workspace_root);
    let mut cache = state
        .workspace_knowledge_cache
        .lock()
        .map_err(|error| format!("workspace knowledge cache lock poisoned: {error}"))?;
    cache.retain(|_, entry| entry.validated_at.elapsed() <= WORKSPACE_KNOWLEDGE_CACHE_TTL);
    if !cache.contains_key(&key) && cache.len() >= WORKSPACE_KNOWLEDGE_CACHE_MAX_ENTRIES {
        let oldest = cache
            .iter()
            .max_by_key(|(_, entry)| entry.validated_at.elapsed())
            .map(|(key, _)| key.clone());
        if let Some(oldest) = oldest {
            cache.remove(&oldest);
        }
    }
    cache.insert(
        key,
        WorkspaceKnowledgeCacheEntry {
            adapter: adapter.clone(),
            validated_at: Instant::now(),
        },
    );
    Ok(())
}

fn invalidate_workspace_knowledge_cache(
    state: &tauri::State<'_, AppState>,
    workspace_root: &Path,
) -> Result<(), String> {
    state
        .workspace_knowledge_cache
        .lock()
        .map_err(|error| format!("workspace knowledge cache lock poisoned: {error}"))?
        .remove(&workspace_knowledge_cache_key(workspace_root));
    Ok(())
}

fn index_graph_chunks(workspace_root: &Path, chunks: &[RagChunk]) -> Result<(usize, usize), String> {
    index_graph_chunks_cancellable(workspace_root, chunks, || false)
}

fn index_graph_chunks_cancellable(
    workspace_root: &Path,
    chunks: &[RagChunk],
    mut should_cancel: impl FnMut() -> bool,
) -> Result<(usize, usize), String> {
    let graph_path = graph_store_path_for(workspace_root);
    if graph_path.exists() {
        fs::remove_file(&graph_path)
            .map_err(|error| format!("failed to reset graph store: {error}"))?;
    }
    let mut graph_store = FileGraphStore::open(&graph_path).map_err(|error| error.to_string())?;
    let mut extractions = Vec::with_capacity(chunks.len());
    for chunk in chunks {
        if should_cancel() {
            drop(graph_store);
            let _ = fs::remove_file(&graph_path);
            return Err(MODEL_REQUEST_CANCELLED.to_string());
        }
        extractions.push(extract_graph_from_chunk(chunk));
    }
    if should_cancel() {
        drop(graph_store);
        let _ = fs::remove_file(&graph_path);
        return Err(MODEL_REQUEST_CANCELLED.to_string());
    }
    graph_store
        .upsert_all(extractions)
        .map_err(|error| error.to_string())?;

    Ok((graph_store.nodes().len(), graph_store.edges().len()))
}

fn workspace_root() -> PathBuf {
    if let Some(root) = runtime_path_from_env("CINDX_DEFAULT_WORKSPACE") {
        if root.is_dir() {
            return root;
        }
    }
    if let Some(home) = user_home_directory() {
        if home.is_dir() {
            return home;
        }
    }
    std::env::current_dir()
        .ok()
        .filter(|path| path.is_dir())
        .unwrap_or_else(std::env::temp_dir)
}

fn app_data_root() -> PathBuf {
    app_data_root_for(
        runtime_path_from_env("CINDX_DATA_DIR"),
        user_home_directory(),
    )
}

fn app_data_root_for(override_root: Option<PathBuf>, home: Option<PathBuf>) -> PathBuf {
    if let Some(root) = override_root {
        return root;
    }
    if let Some(home) = home {
        #[cfg(target_os = "macos")]
        return home.join("Library").join("Application Support").join("Cindx");
        #[cfg(not(target_os = "macos"))]
        return home.join(".cindx");
    }
    std::env::temp_dir().join("Cindx")
}

fn runtime_path_from_env(key: &str) -> Option<PathBuf> {
    let value = std::env::var_os(key)?;
    if value.is_empty() {
        return None;
    }
    let path = PathBuf::from(value);
    if path.is_absolute() {
        Some(path)
    } else {
        std::env::current_dir().ok().map(|current| current.join(path))
    }
}

fn user_home_directory() -> Option<PathBuf> {
    std::env::var_os("HOME")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn migrate_legacy_app_data() -> Result<(), std::io::Error> {
    if runtime_path_from_env("CINDX_DATA_DIR").is_some() {
        return Ok(());
    }
    let source = development_repo_root().join(".cindx");
    let destination = app_data_root();
    if source == destination || !source.is_dir() {
        return Ok(());
    }
    fs::create_dir_all(&destination)?;
    secure_directory(&destination)?;
    for file_name in [
        "state.sqlite3",
        "state.sqlite3-shm",
        "state.sqlite3-wal",
        "provider.conf",
        "workspace.conf",
        "projects.conf",
        "schedules.json",
        "sidecars.conf",
        "mcp-servers.json",
        "mcp-catalog.json",
    ] {
        let source_path = source.join(file_name);
        let destination_path = destination.join(file_name);
        if source_path.is_file() && !destination_path.exists() {
            fs::copy(&source_path, &destination_path)?;
            secure_private_file(&destination_path)?;
        }
    }
    Ok(())
}

fn secure_directory(path: &Path) -> Result<(), std::io::Error> {
    #[cfg(unix)]
    fs::set_permissions(path, fs::Permissions::from_mode(0o700))?;
    Ok(())
}

fn secure_private_file(path: &Path) -> Result<(), std::io::Error> {
    #[cfg(unix)]
    fs::set_permissions(path, fs::Permissions::from_mode(0o600))?;
    Ok(())
}

fn append_startup_log(message: &str) {
    let root = app_data_root();
    if fs::create_dir_all(&root).is_err() {
        return;
    }
    let _ = secure_directory(&root);
    let path = root.join("startup.log");
    let mut options = fs::OpenOptions::new();
    options.create(true).append(true);
    #[cfg(unix)]
    options.mode(0o600);
    let Ok(mut file) = options.open(&path) else {
        return;
    };
    let timestamp_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis())
        .unwrap_or_default();
    let _ = writeln!(file, "{timestamp_ms} {message}");
    let _ = secure_private_file(&path);
}

fn install_startup_panic_log() {
    let previous = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        append_startup_log(&format!("panic: {info}"));
        previous(info);
    }));
}

