    #[test]
    fn session_history_page_reports_a_stable_older_cursor() {
        let mut store = SqliteStore::in_memory().expect("store should open");
        let session_id = "session-history-page";
        for index in 0..7 {
            append_message_event_with_metadata(
                &mut store,
                &phase16_task_id(),
                if index % 2 == 0 {
                    MessageRole::User
                } else {
                    MessageRole::Assistant
                },
                &format!("message-{index}"),
                [("session_id".to_string(), session_id.to_string())]
                    .into_iter()
                    .collect(),
            )
            .expect("message should append");
        }

        let latest = store
            .list_by_task_and_metadata_before(
                &phase16_task_id(),
                "session_id",
                session_id,
                u64::MAX,
                3,
            )
            .expect("latest page should load");
        assert_eq!(
            latest
                .iter()
                .map(|event| event.sequence)
                .collect::<Vec<_>>(),
            vec![5, 6, 7]
        );

        let older = store
            .list_by_task_and_metadata_before(
                &phase16_task_id(),
                "session_id",
                session_id,
                latest[0].sequence,
                3,
            )
            .expect("older page should load");
        assert_eq!(
            older
                .iter()
                .map(|event| event.sequence)
                .collect::<Vec<_>>(),
            vec![2, 3, 4]
        );
        assert!(store
            .has_task_metadata_event_before(
                &phase16_task_id(),
                "session_id",
                session_id,
                older[0].sequence,
            )
            .expect("older cursor should be checked"));
    }

